KI, EKI, KO = r"(\text{気})", r"(\text{液})", r"(\text{固})"

# 熱量測定のデータ（時間〔分〕, 温度〔℃〕）。2分以降は放冷で 0.20 K/分 ずつ直線的に下がる
CAL = [(0, 20.0), (0.5, 25.6), (1.0, 28.6), (1.5, 29.5)] + [(t, round(30.0 - 0.2 * t, 1)) for t in range(2, 11)]


def fig_cal():
    W, H, x0, x1, y0, y1 = 360, 230, 44, 330, 10, 200
    X = lambda t: x0 + t / 10 * (x1 - x0)
    Y = lambda T: y1 - (T - 18) / 14 * (y1 - y0)
    o = [f'<svg class="fig" width="{W}" height="{H}" viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg" font-size="10">']
    for T in range(18, 33):
        o.append(f'<line x1="{x0}" y1="{Y(T):.1f}" x2="{x1}" y2="{Y(T):.1f}" stroke="{"#bbb" if T % 2 == 0 else "#e6e6e6"}"/>')
        if T % 2 == 0:
            o.append(f'<text x="{x0-4}" y="{Y(T)+3:.1f}" text-anchor="end">{T}</text>')
    for t in range(0, 11):
        o.append(f'<line x1="{X(t):.1f}" y1="{y0}" x2="{X(t):.1f}" y2="{y1}" stroke="#e6e6e6"/>')
        if t % 2 == 0:
            o.append(f'<text x="{X(t):.1f}" y="{y1+13}" text-anchor="middle">{t}</text>')
    o.append(f'<rect x="{x0}" y="{y0}" width="{x1-x0}" height="{y1-y0}" fill="none" stroke="#000"/>')
    o.append(f'<line x1="{X(0):.1f}" y1="{Y(30.0):.1f}" x2="{X(10):.1f}" y2="{Y(28.0):.1f}" stroke="#000" stroke-dasharray="5,3"/>')
    o.append('<polyline fill="none" stroke="#000" stroke-width="1.2" points="' +
             " ".join(f"{X(t):.1f},{Y(T):.1f}" for t, T in CAL) + '"/>')
    for t, T in CAL:
        o.append(f'<circle cx="{X(t):.1f}" cy="{Y(T):.1f}" r="2.6"/>')
    o.append(f'<text x="{(x0+x1)/2}" y="{H-4}" text-anchor="middle">NaOH を加えてからの時間〔分〕</text>')
    o.append(f'<text x="12" y="{(y0+y1)/2}" transform="rotate(-90 12 {(y0+y1)/2})" text-anchor="middle">温度〔℃〕</text>')
    o.append("</svg>")
    return "".join(o)


