def _parse(s):
    st, i = [Counter()], 0
    while i < len(s):
        if s[i] in "([":
            st.append(Counter()); i += 1
        elif s[i] in ")]":
            m = re.match(r"\d*", s[i + 1:]); k = int(m.group() or 1); i += 1 + len(m.group())
            top = st.pop()
            for e, c in top.items():
                st[-1][e] += k * c
        else:
            m = re.match(r"([A-Z][a-z]?)(\d*)", s[i:])
            st[-1][m.group(1)] += int(m.group(2) or 1); i += len(m.group())
    return st[0]


def balanced(lhs, rhs):
    def tot(side):
        t = Counter()
        for k, f in side:
            for e, c in _parse(f).items():
                t[e] += k * c
        return +t
    assert tot(lhs) == tot(rhs), (lhs, rhs)


def verify():
    items = CH[7]["items"]
    lv = [it["lv"] for it in items]
    assert lv == sorted(lv) and lv.count("A") == 4 and 4 <= lv.count("B") <= 5 and lv.count("C") == 2
    for it in items:
        for k in ("tag", "q", "a", "s"):
            assert it[k].strip(), k
        for k in ("q", "a", "s"):
            assert it[k].count("$") % 2 == 0 and "$$" not in it[k], it[k][:30]
        assert "<b>ポイント</b>" in it["s"]
    assert CH[7]["goal"].count("$") % 2 == 0

    def sig(x, n=2):
        return round(x, n - 1 - int(floor(log10(abs(x)))))

    def eq(x, v, n=2):
        assert abs(sig(x, n) - v) <= 1e-9 * abs(v), (x, sig(x, n), v)

    # A1
    eq(-137 / (4.60 / 46), -1.37e3, 3); eq(2.6 / (8.0 / 80), 26)
    balanced([(1, "CH4"), (2, "O2")], [(1, "CO2"), (2, "H2O")])
    # A2
    assert -394 - (-283) == -111
    x = (394 * 3.0 - 899) / (394 - 111); eq(x, 1.0)
    # A3
    dh = 3 * -394 + 4 * -286 - (-105); assert dh == -2221; eq(0.25 * 2221, 5.6e2)
    balanced([(1, "C3H8"), (5, "O2")], [(3, "CO2"), (4, "H2O")])
    # A4
    assert 436 + 242 - 2 * 431 == -184 and -184 / 2 == -92
    assert 946 / 2 + 1.5 * 436 - 3 * 391 == -46
    # B1 熱量測定：放冷直線の延長が 0 分で 30.0 ℃
    pts = [(t, T) for t, T in CAL if t >= 2]
    sl = (pts[-1][1] - pts[0][1]) / (pts[-1][0] - pts[0][0]); T0 = pts[0][1] - sl * pts[0][0]
    assert abs(T0 - 30.0) < 1e-9 and max(T for _, T in CAL) == 29.6
    for t, T in pts:
        assert abs(T - (T0 + sl * t)) < 1e-9
    q = 50.0 * 4.2 * (T0 - 20.0); eq(-q / 1000 / (2.00 / 40), -42)
    assert abs(0.50 * 0.100 - 2.00 / 40) < 1e-12
    eq(0.0500 * (42 + 56) * 1000 / (102 * 4.2), 11)
    # B2 燃焼エンタルピーから
    assert 2 * -394 + -286 - (-1301) == 227 and -1301 - 286 - (-1411) == -176 and 3 * -1301 - (-3268) == -635
    balanced([(2, "C2H2"), (5, "O2")], [(4, "CO2"), (2, "H2O")])
    # B3 結合エネルギー
    ch = (75 + 717 + 2 * 436) / 4; assert ch == 416
    cc = 84 + 2 * 717 + 3 * 436 - 6 * ch; assert cc == 330
    comb = (4 * ch + 2 * 498) - (2 * 804 + 4 * 463); assert comb == -800
    assert -394 + 2 * -286 - (-75) == -891 and comb - 2 * 44 == -888
    # B5 光
    E = 6.6e-34 * 3.0e8 / 500e-9; eq(E, 4.0e-19); eq(E * 6.0e23 / 1000, 2.4e2)
    lam = 6.6e-34 * 3.0e8 * 6.0e23 / 242e3; eq(lam * 1e9, 4.9e2)
    n = 2803 / (E * 6.0e23 / 1000); assert 11 < n < 12; eq(n, 11.8, 3)
    balanced([(6, "CO2"), (6, "H2O")], [(1, "C6H12O6"), (6, "O2")])
    # C1 ボルン・ハーバー
    lat = 411 + 107 + 242 / 2 + 496 - 349; assert lat == 786 and lat - 406 - 376 == 4
    # C2 ベンゼン
    a = -3752 - 286 - (-3920); b = -3268 - 3 * 286 - (-3920)
    assert a == -118 and b == -206 and 3 * a == -354 and 3 * a - b == -148
    balanced([(1, "C6H6"), (3, "H2")], [(1, "C6H12")])
